pub fn validate(&self) -> Result<()> {
    self.validate_context(false)
}

// Local research overlay: compressed CM4 carries dynamic blocks only.
pub(crate) fn validate_compressed(&self) -> Result<()> {
    self.validate_context(true)
}

fn validate_context(&self, compressed: bool) -> Result<()> {
    let blocks

if compressed {
    ensure!(blocks.iter().all(|b| matches!(b.level(), 3 | 8 | 9 | 11)),
            "Compressed CM4 supports dynamic L3/L8/L9/L11 only");
    ensure!(level254_count == 0, "Compressed CM4 must inherit L254");
} else {
    ensure!(level254_count == 1, "There must be one L254 metadata block");
}

match cmv40 {
    DmData::V40(blocks) if self.compressed => blocks.validate_compressed(),
    _ => cmv40.validate(),
}.with_context(|| CmV40DmData::VERSION)?;
